SELECT L.ID, L.SEGUNDO, L.TRECHO, V.YT_VIDEO_ID, V.TITULO VIDEO, C.NOME CANAL, (SELECT GROUP_CONCAT(T.TEXTO ORDER BY T.SEGUNDO SEPARATOR ' ') FROM TRECHOS T WHERE T.VIDEO_ID = L.VIDEO_ID AND L.SEGUNDO IS NOT NULL AND T.SEGUNDO BETWEEN L.SEGUNDO - 40 AND L.SEGUNDO + 40) TRANSCRICAO FROM LIVROS_INDICADOS L JOIN VIDEOS V ON V.ID = L.VIDEO_ID JOIN CANAIS C ON C.ID = V.CANAL_ID WHERE L.TITULO COLLATE utf8mb4_0900_ai_ci = (SELECT X.TITULO FROM LIVROS_INDICADOS X WHERE X.ID = {{id}}) ORDER BY V.PUBLICADO_EM DESC, L.SEGUNDO LIMIT 6